def hull_mask(grid, marker=9):
    pts = np.argwhere(grid==marker).astype(float)
    # graham/monotone chain hull on (r,c)
    P = sorted(map(tuple, pts))
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lower=[]
    for p in P:
        while len(lower)>=2 and cross(lower[-2],lower[-1],p)<=0: lower.pop()
        lower.append(p)
    upper=[]
    for p in reversed(P):
        while len(upper)>=2 and cross(upper[-2],upper[-1],p)<=0: upper.pop()
        upper.append(p)
    poly = lower[:-1]+upper[:-1]
    H,W = grid.shape
    m = np.zeros((H,W), bool)
    for r in range(H):
        for c in range(W):
            # ray casting
            inside=False
            n=len(poly)
            for i in range(n):
                x1,y1=poly[i]; x2,y2=poly[(i+1)%n]
                if (y1>c)!=(y2>c):
                    xin = x1+(c-y1)*(x2-x1)/(y2-y1)
                    if xin>r: inside=not inside
            m[r,c]=inside
    return m

